using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using System.Text.RegularExpressions;using System.Net;using System.Net.Http;using System.Security.Cryptography;using System.Threading;using System.Threading.Tasks;
namespace FoolLauncher {
 public sealed class VanillaVersion {
  public string id {get;set;}public string type {get;set;}public string url {get;set;}public string sha1 {get;set;}public string releaseTime {get;set;}
  public string Title {get{return id+"  ·  "+Kind;}}public string Kind {get{return UiText.T(type=="release"?"正式版":type=="snapshot"?"快照 / 预发布版":type=="old_beta"?"远古 Beta":"远古 Alpha");}}
  public string Date {get{DateTime d;return DateTime.TryParse(releaseTime,out d)?d.ToString("yyyy-MM-dd"):"";}}public override string ToString(){return Title;}
 }
 public sealed class VanillaManifest {public Dictionary<string,string> latest {get;set;}public VanillaVersion[] versions {get;set;}}
 public sealed class VanillaService {
  public const string ManifestUrl="https://piston-meta.mojang.com/mc/game/version_manifest_v2.json";
  readonly PackService Service;readonly Func<string,CancellationToken,Task<byte[]>> Fetch;public bool Cached {get;private set;}
  public VanillaService(PackService service):this(service,Read){}internal VanillaService(PackService service,Func<string,CancellationToken,Task<byte[]>> fetch){Service=service;Fetch=fetch;}
  static readonly HttpClient Http=Create();static HttpClient Create(){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;var h=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false,UseCookies=false}){Timeout=Timeout.InfiniteTimeSpan};h.DefaultRequestHeaders.UserAgent.ParseAdd("ZhixiLauncher/0.3.5 (+https://github.com/ZhixiTiancai/ZX-Launcher)");return h;}
  internal static string VersionId(string id){if(!Regex.IsMatch(id??"",@"\A[A-Za-z0-9_][A-Za-z0-9_.+\- ]{0,99}\z")||id!=id.Trim())throw new InvalidDataException("游戏版本号无效。");PackService.SafePath(Path.GetTempPath(),id+".json");return id;}
  static Uri Address(string url){var u=CatalogNetwork.Https(url);if(!new[]{"piston-meta.mojang.com","launchermeta.mojang.com","launcher.mojang.com"}.Contains(u.Host))throw new InvalidDataException("游戏元数据不是 Mojang 官方地址。");return u;}
  static async Task<byte[]> Read(string url,CancellationToken ct){var uri=Address(url);using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct)){timeout.CancelAfter(TimeSpan.FromSeconds(30));using(var response=await Http.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead,timeout.Token).ConfigureAwait(false)){response.EnsureSuccessStatusCode();if(response.Content.Headers.ContentLength>8*1024*1024)throw new IOException("版本清单过大。");using(var input=await response.Content.ReadAsStreamAsync().ConfigureAwait(false))using(var output=new MemoryStream()){var buffer=new byte[32768];int n;while((n=await input.ReadAsync(buffer,0,buffer.Length,timeout.Token).ConfigureAwait(false))>0){if(output.Length+n>8*1024*1024)throw new IOException("版本清单过大。");output.Write(buffer,0,n);}return output.ToArray();}}}}
  internal static VanillaManifest Parse(byte[] bytes){if(bytes==null||bytes.Length>8*1024*1024)throw new InvalidDataException("版本清单无效。");var m=Json.Parse<VanillaManifest>(Encoding.UTF8.GetString(bytes).TrimStart('\uFEFF'));if(m==null||m.versions==null||m.versions.Length==0||m.versions.Length>10000)throw new InvalidDataException("版本清单无效。");var seen=new HashSet<string>();foreach(var v in m.versions){if(v==null||!seen.Add(VersionId(v.id))||!new[]{"release","snapshot","old_beta","old_alpha"}.Contains(v.type)||!Regex.IsMatch(v.sha1??"",@"\A[0-9a-fA-F]{40}\z"))throw new InvalidDataException("版本条目无效。");Address(v.url);}return m;}
  public async Task<VanillaManifest> List(CancellationToken ct){string path=Path.Combine(Service.Data,"metadata","vanilla-manifest.json");Cached=false;byte[] bytes;VanillaManifest result;try{bytes=await Fetch(ManifestUrl,ct).ConfigureAwait(false);result=Parse(bytes);}catch{ct.ThrowIfCancellationRequested();if(!File.Exists(path)||new FileInfo(path).Length>8*1024*1024)throw;result=Parse(File.ReadAllBytes(path));Cached=true;return result;}LauncherUpdateCore.NoLinks(path);Directory.CreateDirectory(Path.GetDirectoryName(path));Json.Write(path,result);return result;}
  internal async Task Verify(VanillaVersion version,CancellationToken ct){VersionId(version.id);Address(version.url);byte[] bytes=await Fetch(version.url,ct).ConfigureAwait(false);if(bytes==null||bytes.Length>8*1024*1024)throw new IOException("版本元数据过大。");string actual;using(var sha=SHA1.Create())actual=BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","");if(!String.Equals(actual,version.sha1,StringComparison.OrdinalIgnoreCase))throw new IOException("官方版本元数据 SHA-1 校验失败。");var m=Json.Parse<Dictionary<string,object>>(Encoding.UTF8.GetString(bytes));object id;if(!m.TryGetValue("id",out id)||Convert.ToString(id)!=version.id)throw new IOException("官方版本编号不匹配。");}
  internal Instance Prepare(VanillaVersion v){VersionId(v.id);var old=Service.List().FirstOrDefault(existing=>existing.Minecraft==v.id&&existing.Loader=="原版");if(old!=null)return old;var i=new Instance{Id="Minecraft-"+v.id.Replace(' ','_')+"-"+Guid.NewGuid().ToString("N").Substring(0,6),Name="Minecraft "+v.id,Version=v.id,Minecraft=v.id,Loader="原版",Ready=false};string folder=Service.Folder(i);LauncherUpdateCore.NoLinks(folder);Directory.CreateDirectory(Service.Game(i));var index=new PackIndex{game="minecraft",formatVersion=1,name=i.Name,versionId=v.id,dependencies=new Dictionary<string,string>{{"minecraft",v.id}},files=new PackFile[0]};Service.Validate(index);Json.Write(Path.Combine(folder,"pack-index.json"),index);Json.Write(Path.Combine(folder,"mmc-pack.json"),new{formatVersion=1,components=new[]{new{uid="net.minecraft",version=v.id,important=true}}});IniConfig.UpdateGeneral(Path.Combine(folder,"instance.cfg"),new Dictionary<string,string>{{"InstanceType","OneSix"},{"name",IniConfig.StringValue(i.Name)},{"OverrideMemory","true"},{"MinMemAlloc","512"},{"MaxMemAlloc","4096"},{"iconKey","default"}});Json.Write(Path.Combine(folder,"launcher-instance.json"),i);return i;}
  public async Task<Instance> Install(VanillaVersion selected,IProgress<Update> progress,Action<Instance> added,CancellationToken ct){var manifest=await List(ct);var version=manifest.versions.FirstOrDefault(v=>v.id==selected.id);if(version==null)throw new IOException("此版本已不在官方清单中，请刷新版本列表。");progress.Report(new Update("校验 Mojang 官方版本："+version.id));await Verify(version,ct);ct.ThrowIfCancellationRequested();var instance=Prepare(version);added(instance);var metadata=new MetadataCache(Service.Data);await metadata.Ensure(Service.Folder(instance),progress,ct);await new GameFiles(Service).Ensure(metadata.VersionFiles,progress,ct);ct.ThrowIfCancellationRequested();int memory=4096;string cfg=Path.Combine(Service.Folder(instance),"instance.cfg");if(File.Exists(cfg)){string line=File.ReadAllLines(cfg).FirstOrDefault(l=>l.StartsWith("MaxMemAlloc="));int value;if(line!=null&&Int32.TryParse(line.Substring(12),out value))memory=value;}Service.ConfigureInstance(instance,memory);instance.Ready=true;Json.Write(Path.Combine(Service.Folder(instance),"launcher-instance.json"),instance);added(instance);return instance;}
 }
}
